import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link, Navigate } from 'react-router-dom';

import { useAuth } from './hooks/useAuth';
import AddRestaurant from './components/restaurant/AddRestaurant';
import EditRestaurant from './components/restaurant/EditRestaurant';
import RestaurantManageDetails from './components/restaurant/RestaurantDashboard'; // Renamed for clarity
import AddMenuItem from './components/restaurant/AddMenuItem';
import EditMenuItem from './components/restaurant/EditMenuItem';
import AdminDashboardPage from './pages/AdminDashboardPage'; // Main Admin Dashboard
import RestaurantAdminDashboardPage from './pages/RestaurantAdminDashboardPage'; // Restaurant Admin Dashboard

function App() {
  const { auth, user } = useAuth();

  return (
    <Router>
      <div>
        <nav>
          <ul>
            <li><Link to="/">Home</Link></li>
            {auth && user?.role === 'restaurant' && (
              <li><Link to="/restaurant/admin">Restaurant Admin</Link></li>
            )}
            {auth && user?.role === 'admin' && (
              <li><Link to="/admin">Admin Dashboard</Link></li>
            )}
            {!auth && <li><Link to="/login">Login</Link></li>}
          </ul>
        </nav>

        <Routes>
          <Route path="/" element={<div>Home Page</div>} />
          <Route path="/login" element={<div>Login Page (Implement Login Form)</div>} />

          {/* Restaurant Admin Routes */}
          <Route path="/restaurant/admin" element={auth && user?.role === 'restaurant' ? <RestaurantAdminDashboardPage /> : <Navigate to="/login" />} />
          <Route path="/restaurant/add" element={auth && user?.role === 'restaurant' ? <AddRestaurant /> : <Navigate to="/login" />} />
          <Route path="/restaurant/edit/:id" element={auth && user?.role === 'restaurant' ? <EditRestaurant /> : <Navigate to="/login" />} />
          <Route path="/restaurant/manage" element={auth && user?.role === 'restaurant' ? <RestaurantManageDetails /> : <Navigate to="/login" />} />
          <Route path="/restaurant/menu/add" element={auth && user?.role === 'restaurant' ? <AddMenuItem /> : <Navigate to="/login" />} />
          <Route path="/restaurant/menu/edit/:id" element={auth && user?.role === 'restaurant' ? <EditMenuItem /> : <Navigate to="/login" />} />

          {/* Admin Routes */}
          <Route path="/admin" element={auth && user?.role === 'admin' ? <AdminDashboardPage /> : <Navigate to="/login" />} />

          {/* ... other routes */}
        </Routes>
      </div>
    </Router>
  );
}

export default App;
